  /**
   * Reaching executions in the most recent fuzz session — the signal REFLECT compares round over round.
   */
  last_reached_count?: number
  triggered_count: number
  timeout_count?: number
  error_count?: number
  /**
   * Summary of the most recent `pbfuzz_fuzz` job.
   */
