    iterations?: number
    reached?: number
    triggered?: number
    timeouts?: number
    errors?: number
    elapsed_sec?: number
    stopped_by?: 'completed' | 'timeout' | 'trigger' | 'error' | 'cancelled'
    first_triggering_input?: string
    best_reaching_input?: string
