  current_task: string
  next_action: string
  /**
   * Completed PLAN→REFLECT cycles. `state-writer.ts`'s `advancePhase()` redirects a REFLECT→PLAN request to STOPPED once this reaches `maxPierRounds`, instead of the caller-requested PLAN.
   */
